<?php
/**
 * The registry catalog and its version ranges.
 *
 * @package ZoremAgentBrain
 */

declare( strict_types=1 );

namespace ZoremAgentBrain\V1\Curated;

defined( 'ABSPATH' ) || exit;

/**
 * Reads `index.json` and answers which entry files apply to a version.
 *
 * The catalog is the registry's only JSON file, and it is generated by
 * RegistryExporter rather than hand-edited — the `.md` entries are what a human
 * writes. Shape:
 *
 *     {
 *       "schema_version": 1,
 *       "generated_at": "…",
 *       "plugins": {
 *         "woocommerce": {
 *           "ranges": [
 *             { "min": "10.9", "max": "11.99", "entries": [ { "file": "…md", "checksum": "…" } ] }
 *           ]
 *         }
 *       }
 *     }
 *
 * Range resolution picks the **newest** range whose bounds contain the
 * installed version, so a catalog can carry knowledge for several releases at
 * once and a site gets the one written for what it is running. A version
 * outside every range is not covered — and "not covered" means local extraction
 * proceeds, which is the safe direction.
 */
final class CatalogIndex {

	/**
	 * Decoded catalog.
	 *
	 * @var array<string, mixed>
	 */
	private array $data;

	/**
	 * Constructor.
	 *
	 * @param array<string, mixed> $data Decoded catalog.
	 */
	public function __construct( array $data ) {
		$this->data = $data;
	}

	/**
	 * Parse a catalog document.
	 *
	 * @param string $json Raw index.json.
	 * @return self|\WP_Error
	 */
	public static function from_json( string $json ) {
		$decoded = json_decode( $json, true );

		if ( ! is_array( $decoded ) || ! isset( $decoded['plugins'] ) || ! is_array( $decoded['plugins'] ) ) {
			return new \WP_Error(
				'zorem_agent_brain_registry_invalid_catalog',
				__( 'The registry catalog is not valid JSON, or has no plugins map.', 'zorem-ai-agent-connector' )
			);
		}

		return new self( $decoded );
	}

	/**
	 * Every plugin slug the catalog mentions.
	 *
	 * @return array<int, string>
	 */
	public function slugs(): array {
		return array_map( 'strval', array_keys( (array) $this->data['plugins'] ) );
	}

	/**
	 * The entry files covering one plugin version.
	 *
	 * @param string $slug    Plugin slug.
	 * @param string $version Installed version.
	 * @return array<int, array<string, string>> Entry descriptors.
	 */
	public function entries_for( string $slug, string $version ): array {
		$range = $this->range_for( $slug, $version );

		if ( null === $range ) {
			return array();
		}

		$entries = array();

		foreach ( (array) ( $range['entries'] ?? array() ) as $entry ) {
			if ( ! is_array( $entry ) || empty( $entry['file'] ) ) {
				continue;
			}

			$file = (string) $entry['file'];

			/*
			 * The catalog names files inside the registry. A name that climbs
			 * out of it — or that is absolute — is refused rather than
			 * normalised, because a catalog is remote input and path traversal
			 * is the obvious thing to try with it.
			 */
			if ( ! self::is_safe_relative_path( $file ) ) {
				continue;
			}

			$entries[] = array(
				'file'     => $file,
				'checksum' => (string) ( $entry['checksum'] ?? '' ),
			);
		}

		return $entries;
	}

	/**
	 * Whether a catalog covers a plugin version at all.
	 *
	 * @param string $slug    Plugin slug.
	 * @param string $version Installed version.
	 */
	public function supports( string $slug, string $version ): bool {
		return array() !== $this->entries_for( $slug, $version );
	}

	/**
	 * The newest range containing a version.
	 *
	 * @param string $slug    Plugin slug.
	 * @param string $version Installed version.
	 * @return array<string, mixed>|null
	 */
	private function range_for( string $slug, string $version ): ?array {
		$plugin = $this->data['plugins'][ $slug ] ?? null;

		if ( ! is_array( $plugin ) || ! isset( $plugin['ranges'] ) || ! is_array( $plugin['ranges'] ) ) {
			return null;
		}

		$best = null;

		foreach ( $plugin['ranges'] as $range ) {
			if ( ! is_array( $range ) ) {
				continue;
			}

			$min = (string) ( $range['min'] ?? '' );
			$max = (string) ( $range['max'] ?? '' );

			if ( '' !== $min && version_compare( $version, $min, '<' ) ) {
				continue;
			}

			if ( '' !== $max && version_compare( $version, $max, '>' ) ) {
				continue;
			}

			// Newest wins: the range with the highest lower bound.
			if ( null === $best || version_compare( $min, (string) ( $best['min'] ?? '' ), '>' ) ) {
				$best = $range;
			}
		}

		return $best;
	}

	/**
	 * Whether a catalog-supplied path stays inside the registry.
	 *
	 * @param string $path Relative path from the catalog.
	 */
	public static function is_safe_relative_path( string $path ): bool {
		if ( '' === $path || strlen( $path ) > 255 ) {
			return false;
		}

		$normalized = str_replace( '\\', '/', $path );

		if ( 0 === strpos( $normalized, '/' ) || preg_match( '#^[a-zA-Z]:#', $normalized ) ) {
			return false;
		}

		if ( false !== strpos( $normalized, '../' ) || false !== strpos( $normalized, "\0" ) ) {
			return false;
		}

		return (bool) preg_match( '#^[a-z0-9][a-z0-9._/-]*\.md$#i', $normalized );
	}
}
